/**
 * NOVA HYPOTHESIS FORGE — counter-evidence engine.
 *
 * The system actively tries to undermine its own hypothesis. Findings are
 * generated from the data actually retrieved (gaps, cadence mismatches,
 * unavailable sources) and from the hypothesis' own stated assumptions and
 * alternatives. Nothing here is generated by a language model, and nothing here
 * is hidden from the final report: every finding is returned to the UI and the
 * Evidence Passport.
 */

import type {
  AnalysisResult,
  CounterEvidenceFinding,
  CounterEvidenceReport,
  DatasetResult,
  EvidenceItem,
  Hypothesis,
  LanguageCode,
  ResearchPlan,
  ResearchRequest,
} from './types';
import { datasetById } from './vocab';
import { forgeText, variableLabel } from './strings';

const SEVERITY_RANK: Record<CounterEvidenceFinding['severity'], number> = {
  low: 1,
  medium: 2,
  high: 3,
};

function add(
  findings: CounterEvidenceFinding[],
  finding: Omit<CounterEvidenceFinding, 'id'>,
): void {
  findings.push({ id: `CE-${findings.length + 1}`, ...finding });
}

export function buildCounterEvidence(args: {
  request: ResearchRequest;
  plan: ResearchPlan;
  datasets: DatasetResult[];
  analyses: AnalysisResult[];
  evidence: EvidenceItem[];
  hypotheses: Hypothesis[];
  language: LanguageCode;
}): CounterEvidenceReport {
  const { request, datasets, analyses, evidence, hypotheses, language } = args;
  const findings: CounterEvidenceFinding[] = [];

  /* 1. Missing sources / data gaps -------------------------------------- */
  for (const result of datasets) {
    const dataset = datasetById(result.datasetId);
    const title = dataset?.title ?? result.datasetId;
    if (result.status === 'out-of-coverage') {
      add(findings, {
        kind: 'data-gap',
        severity: 'high',
        title: forgeText(language, 'ce_out_of_coverage_title'),
        detail: forgeText(language, 'ce_out_of_coverage_detail', {
          dataset: title,
          coverage: dataset?.coverage.description ?? 'published window',
        }),
      });
      continue;
    }
    if (result.status === 'unavailable' || result.status === 'not-requested') {
      add(findings, {
        kind: 'data-gap',
        severity: 'high',
        title: forgeText(language, 'ce_data_gap_title'),
        detail: `${forgeText(language, 'ce_data_gap_detail', { dataset: title })} ${
          result.detail ?? ''
        }`.trim(),
      });
      continue;
    }
    for (const series of result.series) {
      if (series.missing.fraction >= 0.2) {
        add(findings, {
          kind: 'data-gap',
          severity: 'high',
          title: forgeText(language, 'ce_data_gap_title'),
          detail: `${title} — ${series.label}: ${forgeText(language, 'rule_missing_coverage', {
            coverage: (100 * (1 - series.missing.fraction)).toFixed(1),
          })}`,
        });
      }
    }
  }

  if (datasets.every((result) => result.series.length === 0)) {
    add(findings, {
      kind: 'data-gap',
      severity: 'high',
      title: forgeText(language, 'ce_data_gap_title'),
      detail: forgeText(language, 'rule_no_data'),
    });
  }

  /* 2. Temporal alignment ------------------------------------------------ */
  for (const analysis of analyses) {
    const driverCadence = analysis.parameters.driverCadence;
    const responseCadence = analysis.parameters.responseCadence;
    if (
      typeof driverCadence === 'string' &&
      typeof responseCadence === 'string' &&
      driverCadence !== responseCadence
    ) {
      add(findings, {
        kind: 'temporal-mismatch',
        severity: 'medium',
        title: forgeText(language, 'ce_temporal_title'),
        detail: forgeText(language, 'ce_temporal_detail', {
          left: driverCadence,
          right: responseCadence,
        }),
      });
      break;
    }
  }

  /* 3. Assumptions not tested ------------------------------------------- */
  const assumptionsSeen = new Set<string>();
  for (const analysis of analyses) {
    for (const assumption of analysis.assumptions) {
      if (assumptionsSeen.has(assumption)) continue;
      assumptionsSeen.add(assumption);
      if (assumptionsSeen.size > 3) break;
      add(findings, {
        kind: 'assumption',
        severity: 'medium',
        title: forgeText(language, 'ce_assumption_title'),
        detail: forgeText(language, 'ce_assumption_detail', { assumption }),
      });
    }
  }

  /* 4. Alternative explanations from the hypothesis itself --------------- */
  const alternatives = new Set<string>();
  for (const hypothesis of hypotheses) {
    for (const alternative of hypothesis.alternativeExplanations) {
      if (alternatives.has(alternative)) continue;
      alternatives.add(alternative);
      add(findings, {
        kind: 'alternative-explanation',
        severity: 'medium',
        title: forgeText(language, 'ce_alternative_title'),
        detail: alternative,
      });
    }
  }

  /* 5. Measurement uncertainty ------------------------------------------ */
  const estimateDatasets = datasets.filter(
    (result) =>
      result.series.length > 0 &&
      (result.datasetId === 'nasa-neows' || result.datasetId === 'nasa-donki'),
  );
  if (estimateDatasets.length > 0) {
    const variables = estimateDatasets
      .flatMap((result) => result.series.map((series) => variableLabel(language, series.variableId)))
      .join(', ');
    add(findings, {
      kind: 'measurement-uncertainty',
      severity: 'medium',
      title: forgeText(language, 'ce_uncertainty_title'),
      detail: forgeText(language, 'ce_uncertainty_detail', {
        detail: `${variables} — ${forgeText(language, 'lim_estimate')}`,
      }),
    });
  } else if (datasets.some((result) => result.series.length > 0)) {
    add(findings, {
      kind: 'measurement-uncertainty',
      severity: 'low',
      title: forgeText(language, 'ce_uncertainty_title'),
      detail: forgeText(language, 'ce_uncertainty_detail', {
        detail: forgeText(language, 'lim_single_point'),
      }),
    });
  }

  /* 6. Selection bias ---------------------------------------------------- */
  if (request.domain === 'near-earth-objects' || request.domain === 'space-weather') {
    add(findings, {
      kind: 'selection-bias',
      severity: 'medium',
      title: forgeText(language, 'ce_selection_title'),
      detail: forgeText(language, 'alt_selection'),
    });
  }

  /* 7. Missing variable -------------------------------------------------- */
  if (request.domain === 'space-weather' || request.domain === 'earth-environment') {
    add(findings, {
      kind: 'missing-variable',
      severity: 'medium',
      title: forgeText(language, 'ce_missing_variable_title'),
      detail: forgeText(language, 'alt_other_driver'),
    });
  }

  /* 8. Falsification criteria (one entry per hypothesis) ----------------- */
  for (const hypothesis of hypotheses) {
    if (hypothesis.falsificationCriteria.length === 0) continue;
    add(findings, {
      kind: 'falsification',
      severity: 'low',
      title: forgeText(language, 'ce_falsification_title'),
      detail: hypothesis.falsificationCriteria.join(' '),
    });
  }

  /* 9. Insufficient evidence anywhere ------------------------------------ */
  if (evidence.filter((item) => item.classification === 'supporting').length === 0) {
    add(findings, {
      kind: 'falsification',
      severity: 'low',
      title: forgeText(language, 'verdict_insufficient_title'),
      detail: forgeText(language, 'verdict_insufficient_summary'),
    });
  }

  const severity = findings.reduce<CounterEvidenceFinding['severity']>(
    (worst, finding) =>
      SEVERITY_RANK[finding.severity] > SEVERITY_RANK[worst] ? finding.severity : worst,
    'low',
  );

  return {
    findings,
    severity,
    dataGapDetected: findings.some((finding) => finding.kind === 'data-gap'),
  };
}
